kn=json.load(open('known-forms.json'))
B={}
def add(k,new):
    B[k]=kn[k]+" · "+new
add("actor","also the Auruncan Actor, former owner of a captured spear (nom. sg.)")
add("aequum","also n. nom. sg. as predicate (aequum est, it is fitting, right)")
add("agat","also jussive (let him lead)")
add("ardentis","also m./f. gen. sg. (ardentis … ōre, of one blazing)")
add("aurunci","also Auruncus, -ī (m.), an Auruncan (gen. sg.)")
add("columnae","also dat. sg. (adnixa columnae, leaning on a column)")
add("mater","also voc. sg. (ō mater)")
add("mixta","also n. nom. pl. (lilia mixta)")
add("vocatus","also vocātus, -ūs (m.), a calling, summons, prayer (acc. pl.)")
out=dict(G); out["__broaden__"]=B
json.dump(out,open('gloss.json','w'),ensure_ascii=False,indent=1)
nov=json.load(open('novel-forms.json'))
print("novel",len(nov),"missing",[f for f in nov if f not in G],"extra",[f for f in G if f not in nov])
print("over230",[(k,len(v)) for k,v in G.items() if len(v)>=230],[(k,len(v)) for k,v in B.items() if len(v)>=230])
print(len(G),len(B))
